(() => {
  'use strict';
  const M=window.SBModel, started=Date.now(), state={zones:M.createZones(started), offset:0, floor:1, quiet:false,power:false,selected:'Z01',receipt:null};
  const main=document.querySelector('#content'), announcer=document.querySelector('#announce');
  const now=()=>started+state.offset;
  const zoneById=id=>state.zones.find(z=>z.id===id)||state.zones[0];
  const h=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const tag=(label,cls)=>'<span class="badge '+h(cls||label.toLowerCase())+'"><span class="dot"></span>'+h(label)+'</span>';
  const fmtTime=t=>t===null?'No report':new Intl.DateTimeFormat('en-GB',{hour:'2-digit',minute:'2-digit'}).format(new Date(t));
  const age=s=>s.future?'Not yet reported at this demo time':s.age===null?'No report':(s.expired?'Expired · ':'')+Math.floor(s.age/60000)+'m '+String(Math.floor((s.age%60000)/1000)).padStart(2,'0')+'s ago';
  const crumb=(label)=>'<div class="breadcrumbs"><a href="#home">Home</a> <span aria-hidden="true">/</span> '+h(label)+'</div>';
  const head=(eye,title,description)=>'<div class="page-head"><div class="eyebrow">'+h(eye)+'</div><h1>'+h(title)+'</h1><p>'+h(description)+'</p></div>';
  function home(){return '<div class="wrap"><section class="hero"><div><div class="eyebrow">A LITTLE QUIETER, TOGETHER</div><h1>Find your space.<br><em>Keep your focus.</em></h1><p>A quieter study spot. A reported free outlet. See what your campus community could share, all in one simple map.</p><div class="actions"><a class="button" href="#map">Explore the campus map <span>↗</span></a><button class="button ghost" type="button" data-action="how">How it works <span>↓</span></button></div></div><div class="hero-visual"><span class="visual-label">ILLUSTRATIVE CAMPUS VIEW / 01</span><div class="mini-map"><div class="mini-heading"><strong>Campus study map</strong><span class="pill">Floor 01</span></div><div class="mini-cells"><div class="mini-cell">● QUIET<br><br>North study corner</div><div class="mini-cell warm">● MODERATE<br><br>Collaboration tables</div><div class="mini-cell red">● LOUD<br><br>Atrium study area</div><div class="mini-cell white">● UNKNOWN<br><br>Window workspace</div></div></div><div class="floating-card">◉ &nbsp; A more informed choice<span>Example observations, not live data</span></div></div></section><div class="trust-strip"><div><strong>2 floors</strong><span>Illustrative schematic layout</span></div><div><strong>30 minutes</strong><span>Simulated report freshness</span></div><div><strong>1 community</strong><span>Built around shared observations</span></div></div><section class="section" id="home-how"><div class="section-heading"><div><div class="eyebrow">SIMPLE BY DESIGN</div><h2>Know before you go.</h2></div><p>Choose a space that fits your work, and help the next student do the same.</p></div><div class="how-grid"><article class="how-card"><span class="number">01 / EXPLORE</span><h3>Find your floor</h3><p>Browse study areas in a clearly labeled, schematic campus map.</p></article><article class="how-card"><span class="number">02 / DECIDE</span><h3>Check the details</h3><p>Compare noise, outlet availability and the age of each observation.</p></article><article class="how-card"><span class="number">03 / CONTRIBUTE</span><h3>Share an update</h3><p>Walk through a simulated community report. No real report is sent.</p></article></div></section></div>'}
  function map(){const zones=state.zones.filter(z=>z.floor===state.floor&&M.matches(z,now(),state));const tiles=zones.map((z,i)=>{const s=M.status(z,now());return (i===3?'<div class="corridor">SCHEMATIC CORRIDOR · NOT AN OFFICIAL FLOOR PLAN</div>':'')+'<a class="zone" href="#zone/'+z.id+'" aria-label="View '+h(z.name)+', '+h(s.noise.value)+', outlets '+h(s.outlet.value)+'"><div class="zone-top"><span class="zone-id">'+h(z.id)+'</span>'+tag(s.noise.value)+'</div><h3>'+h(z.name)+'</h3><p>⚡ Outlets: '+h(s.outlet.value)+'</p><p>Noise: '+age(s.noise)+'</p></a>';}).join('');return '<div class="wrap">'+head('FIND YOUR PLACE','Explore study zones.','Use the filters to find a space that suits your work. All locations and observations are demonstration examples.')+'<div class="dashboard"><aside class="card sidebar"><h2>Refine your search</h2><span class="field-label">CHOOSE A FLOOR</span><div class="segmented" role="group" aria-label="Choose a floor"><button data-floor="1" class="'+(state.floor===1?'active':'')+'" aria-pressed="'+(state.floor===1)+'">Floor 01</button><button data-floor="2" class="'+(state.floor===2?'active':'')+'" aria-pressed="'+(state.floor===2)+'">Floor 02</button></div><span class="field-label">WHAT MATTERS TO YOU</span><label class="check"><input type="checkbox" id="quiet" '+(state.quiet?'checked':'')+'> Quiet only</label><label class="check"><input type="checkbox" id="power" '+(state.power?'checked':'')+'> Available outlet</label><button class="button small soft" data-action="reset-filters">Clear filters</button><hr class="rule"><span class="field-label">NOISE LEVELS</span><div class="legend">'+['Quiet','Moderate','Loud','Unknown'].map(v=>tag(v)).join('')+'</div><hr class="rule"><div class="side-note">Fresh for less than 30 minutes. Noise and outlet observations expire independently.</div></aside><section aria-label="Floor map"><div class="map-top"><div><h2>Floor 0'+state.floor+' <span class="pill">SCHEMATIC</span></h2><p>'+zones.length+' matching '+(zones.length===1?'zone':'zones')+' · select a zone to see details</p></div><a class="button small ghost" href="#report">+ Add report</a></div><div class="zone-map"><p class="map-note">FLOOR 0'+state.floor+' / ILLUSTRATIVE ZONE MAP</p>'+(zones.length?'<div class="zone-grid">'+tiles+'</div>':'<div class="empty"><h3>No matching zones</h3><p>Try clearing a filter or choosing another floor. Unknown and expired reports never count as Quiet or Available.</p><button class="button small ghost" data-action="reset-filters">Clear filters</button></div>')+'</div><div class="bottom-note"><span>○ Demo clock: '+fmtTime(now())+' · reports are not live</span><a href="#expired/'+state.selected+'">See expiry example →</a></div><div class="card" style="margin-top:18px"><span class="field-label" style="margin-top:0">EXPLORE TIME · DEMO ONLY</span><p class="muted">Advance the simulated clock to see reports become Unknown. No real time or campus data is changed.</p><div class="actions" style="margin-top:12px"><button class="button small ghost" data-action="advance15">+ 15 minutes</button><button class="button small ghost" data-action="advance30">+ 30 minutes</button><button class="button small ghost" data-action="reset-clock">Reset demo clock</button></div></div></section></div></div>'}
  function details(z){const s=M.status(z,now());return '<div class="wrap"><div class="page-head">'+crumb('Study zone')+'<div class="eyebrow">FLOOR 0'+z.floor+' / '+z.id+'</div><h1>'+h(z.name)+'.</h1><p>Make an informed choice with independently timed example observations.</p></div><div class="detail-layout"><div><div class="detail-hero"><div><span class="pill">SCHEMATIC CAMPUS ZONE</span><h2>'+h(z.type)+'</h2><span class="muted">Floor 0'+z.floor+' · Zone '+z.id+' · demonstration only</span></div><div class="legend">'+tag(s.noise.value)+'</div></div><div class="observation-grid"><article class="card observation"><h3>NOISE OBSERVATION</h3><div class="value">'+h(s.noise.value)+'</div><p>'+age(s.noise)+' · observed '+fmtTime(z.noise.at)+'</p><p>Community example, not a measured condition.</p></article><article class="card observation"><h3>OUTLET OBSERVATION</h3><div class="value">'+h(s.outlet.value)+'</div><p>'+age(s.outlet)+' · observed '+fmtTime(z.outlet.at)+'</p><p>Availability may change before you arrive.</p></article></div></div><aside class="stack"><div class="card"><h2>Help the next student.</h2><p class="muted">Share an example of what you notice. This prototype does not send or store campus reports.</p><a class="button" href="#report/'+z.id+'">Add an example report ↗</a></div><div class="card"><h2>Check report freshness</h2><p class="muted">At 30:00 an observation becomes Unknown. Each field has its own age.</p><a class="button small ghost" href="#expired/'+z.id+'">Explore expiry state →</a></div><a class="button ghost" href="#map">← Back to floor map</a></aside></div></div>'}
  function report(z){return '<div class="wrap">'+head('COMMUNITY CHECK-IN','Share what you notice.','Try a simulated report for an illustrative zone. Nothing is submitted to a server or the university.')+'<form class="card form-card" id="report-form"><div class="eyebrow">MANUAL REPORT / DEMONSTRATION</div><h2 style="margin-top:14px">Your example observation</h2><div class="notice">This is a simulation. Campus-network eligibility is not checked, reports are not sent, and data is kept only in this open page.</div><label class="field">STUDY ZONE<select name="zone">'+state.zones.map(x=>'<option value="'+x.id+'" '+(x.id===z.id?'selected':'')+'>'+h(x.id+' · Floor '+x.floor+' · '+x.name)+'</option>').join('')+'</select></label><label class="field">NOISE CATEGORY<select name="noise" required><option value="">Choose an observation</option><option>Quiet</option><option>Moderate</option><option>Loud</option></select></label><label class="field">OUTLET AVAILABILITY<select name="outlet" required><option value="">Choose an observation</option><option>Available</option><option>None available</option><option>Unknown</option></select></label><p class="muted">Please choose based on the example scenario; no personal details or audio are collected.</p><div id="form-error" role="alert"></div><div class="actions"><button class="button" type="submit">Submit example report ↗</button><button class="button ghost" type="button" data-action="blocked">View blocked example</button><a class="button ghost" href="#map">Cancel</a></div></form></div>'}
  function verification(){const r=state.receipt;if(!r)return '<div class="wrap">'+head('REPORT STATUS','No example report yet.','Start with a simulated manual report to see how the status screen works.')+'<div class="card page-content"><a class="button" href="#report">Create an example report →</a></div></div>';const z=zoneById(r.id);return '<div class="wrap">'+head('REPORT STATUS','Example report accepted.','Simulation only. No real submission, location check or campus verification has occurred.')+'<div class="split page-content"><div class="card"><div class="result-icon">✓</div><div class="eyebrow">SIMULATED RECEIPT</div><h2 style="margin-top:15px">'+h(z.name)+'</h2><p>'+tag(r.noise)+' &nbsp; '+h(r.outlet)+' outlets</p><p class="muted">Example '+h(z.id)+' · observed '+fmtTime(r.at)+' · expires at '+fmtTime(r.at+M.TTL)+'</p><div class="notice">This state demonstrates what feedback could look like. It does not prove that a report is accurate or a contributor is on campus.</div><div class="actions"><a class="button" href="#zone/'+z.id+'">View updated zone ↗</a><a class="button ghost" href="#map">Back to map</a></div></div><div class="card"><h2>What happens next?</h2><p class="muted">In this session the demonstration map reflects the example values you selected. Reloading the page resets them.</p><hr class="rule"><a href="#rewards"><strong>Explore proposed rewards →</strong></a></div></div></div>'}
  function blocked(){return '<div class="wrap">'+head('REPORT STATUS','Unable to submit.','A simulated eligibility error explains a possible next step.')+'<div class="card form-card"><div class="result-icon" style="background:#fbeae1;color:#b9694d">!</div><h2>Campus eligibility could not be confirmed</h2><div class="notice alert">Demonstration only: this prototype does not inspect your network. In a future system, a trusted campus check could determine eligibility; it would not verify the exact zone or report accuracy.</div><div class="actions"><a class="button" href="#report/'+state.selected+'">Return to manual report</a><a class="button ghost" href="#map">Browse the map</a></div></div></div>'}
  function rewards(){return '<div class="wrap">'+head('A CONCEPT TO DISCUSS','A little help. A better campus.','Proposed Social GPA recognition is simulated and subject to university approval.')+'<div class="split page-content"><div class="card"><div class="eyebrow">PROPOSED / NOT APPROVED</div><h2 style="font-size:26px;margin-top:15px">Good information helps everyone.</h2><p class="muted">This concept explores recognition for useful contributions while discouraging spam. Eligibility, moderation and any academic implications would require university approval.</p><div class="notice alert"><strong>Simulated rewards only.</strong> No academic credit is awarded and no university policy is implied.</div><div class="actions"><a class="button" href="#report">Try an example report →</a></div></div><div class="card"><div class="eyebrow">DEMONSTRATION ACTIVITY</div><div class="stats" style="grid-template-columns:1fr 1fr"><div class="stat"><strong>'+(state.receipt?'1':'0')+'</strong><span>Example reports this session</span></div><div class="stat"><strong>0</strong><span>Official Social GPA credits</span></div></div><p class="muted">The display is not a real account, score or university record.</p></div></div></div>'}
  function analytics(){const counts={Quiet:0,Moderate:0,Loud:0,Unknown:0},outlets={Available:0,'None available':0,Unknown:0};state.zones.forEach(z=>{const s=M.status(z,now());counts[s.noise.value]++;outlets[s.outlet.value]++;});const rows=Object.entries(counts).map(([k,n])=>'<div class="chart-row"><strong>'+k+'</strong><div class="bar"><i style="width:'+(n/10*100)+'%"></i></div><span>'+n+'</span></div>').join('');return '<div class="wrap">'+head('CAMPUS INSIGHTS','A clearer picture, together.','Administrative view using synthetic demonstration data. These are not measured campus findings.')+'<div class="notice alert"><strong>DEMONSTRATION DATA.</strong> Counts are derived from ten invented zones in this page, including your session-only example reports.</div><div class="stats"><div class="card stat"><strong>10</strong><span>Illustrative study zones</span></div><div class="card stat"><strong>'+counts.Loud+'</strong><span>Zones with simulated Loud status</span></div><div class="card stat"><strong>'+outlets['None available']+'</strong><span>Zones with simulated no-outlet status</span></div></div><div class="split page-content"><div class="card"><h2>Noise categories</h2><p class="muted">Illustrative current zone states · demo clock '+fmtTime(now())+'</p>'+rows+'</div><div class="card"><h2>Questions to explore</h2><p class="muted">A noisy atrium example may suggest a question about study-space separation. An insufficient-outlets example may prompt a review of power access.</p><hr class="rule"><p class="muted">These example indicators are not evidence of campus conditions and must not be presented as research.</p><a class="button small ghost" href="#map">Explore example zones →</a></div></div></div>'}
  function expired(z){const s=M.status(z,now());return '<div class="wrap">'+head('REPORT FRESHNESS','When information gets old.','Explore an example boundary. At exactly 30:00, an observation becomes Unknown.')+'<div class="card form-card"><div class="eyebrow">'+h(z.id)+' / '+h(z.name)+'</div><div class="observation-grid"><div class="observation"><h3>NOISE</h3><div class="value">'+h(s.noise.value)+'</div><p>'+age(s.noise)+'</p></div><div class="observation"><h3>OUTLETS</h3><div class="value">'+h(s.outlet.value)+'</div><p>'+age(s.outlet)+'</p></div></div><hr class="rule"><div class="notice">Fields expire independently. An Unknown noise or outlet state cannot satisfy the Quiet + Available filter. This is a client-side simulation; no authoritative server clock is present.</div><div class="actions"><button class="button ghost" data-action="boundary" '+(z.noise.at===null?'disabled':'')+'>Set noise age to 29:59</button><button class="button" data-action="plus1">Advance 1 second →</button><button class="button ghost" data-action="reset-clock">Reset demo</button></div>'+(z.noise.at===null?'<p class="muted">This zone has no noise report. Choose a zone with a report to explore the boundary.</p>':'')+'<div class="actions"><a class="button small ghost" href="#zone/'+z.id+'">← Zone details</a><a class="button small ghost" href="#map">Open floor map</a><a class="button small ghost" href="#report/'+z.id+'">Add example report</a></div></div></div>'}
  function render(){const parts=location.hash.replace(/^#/,'').split('/'),route=parts[0]||'home';if(parts[1]&&state.zones.some(z=>z.id===parts[1]))state.selected=parts[1];const z=zoneById(state.selected);const views={home:()=>home(),map:()=>map(),zone:()=>details(z),report:()=>report(z),verification:()=>verification(),blocked:()=>blocked(),rewards:()=>rewards(),analytics:()=>analytics(),expired:()=>expired(z)};main.innerHTML=(views[route]||views.home)();document.title=(route==='home'?'SilentBeacon — campus study map':route[0].toUpperCase()+route.slice(1)+' | SilentBeacon');}
  function rerender(message){render();if(message)announcer.textContent=message;}
  document.addEventListener('click',e=>{const button=e.target.closest('button');if(!button)return;if(button.dataset.floor){state.floor=Number(button.dataset.floor);rerender('Floor '+state.floor+' selected');return;}switch(button.dataset.action){case'how':document.querySelector('#home-how').scrollIntoView({behavior:'smooth'});break;case'reset-filters':state.quiet=false;state.power=false;rerender('Filters cleared');break;case'advance15':state.offset+=15*60000;rerender('Demo clock advanced 15 minutes');break;case'advance30':state.offset+=30*60000;rerender('Demo clock advanced 30 minutes');break;case'reset-clock':state.offset=0;state.zones=M.createZones(started);state.receipt=null;rerender('Demo reset to original example data');break;case'boundary':{const t=zoneById(state.selected).noise.at;if(t!==null){state.offset=t+M.TTL-1000-started;rerender('Noise report age set to 29 minutes 59 seconds');}break;}case'plus1':state.offset+=1000;rerender('Demo clock advanced one second');break;case'blocked':location.hash='blocked';break;}});
  document.addEventListener('change',e=>{if(e.target.name==='zone')state.selected=e.target.value;if(e.target.id==='quiet'){state.quiet=e.target.checked;rerender('Quiet filter updated');}if(e.target.id==='power'){state.power=e.target.checked;rerender('Outlet filter updated');}});
  document.addEventListener('submit',e=>{if(e.target.id!=='report-form')return;e.preventDefault();const form=new FormData(e.target),z=zoneById(form.get('zone'));try{M.submit(z,form.get('noise'),form.get('outlet'),now());state.selected=z.id;state.receipt={id:z.id,noise:form.get('noise'),outlet:form.get('outlet'),at:now()};location.hash='verification';}catch(err){document.querySelector('#form-error').textContent=err.message;}});
  window.addEventListener('hashchange',()=>{render();main.focus({preventScroll:true});window.scrollTo(0,0);});
  render();
})();
